@pytest.mark.parametrize("invoke_mode", ["invoke", "ainvoke"])
@pytest.mark.parametrize("ptc", [None, [], [lookup]])
async def test_signed_snapshot_survives_model_only_turns_and_rebuilt_agent(
    monkeypatch, invoke_mode, ptc
) -> None:
    saver = InMemorySaver()
    config = {"configurable": {"thread_id": "signed-lazy-resume"}}

    def build(messages):
        return create_agent(
            model=FakeChatModel(messages=iter(messages)),
            middleware=[
                CodeInterpreterMiddleware(
                    snapshot_signing_key=b"deterministic-test-key", ptc=ptc
                )
            ],
            checkpointer=saver,
        )

    def checkpoint(agent):
        state = agent.get_state(config).values
        return tuple(
            state[key]
            for key in (
                "_quickjs_slot_id",
                "_quickjs_snapshot_payload",
                "_quickjs_snapshot_hmac",
            )
        )

    agent = build(
        [
            _call("const counter = 41", "define"),
            AIMessage(content="Saved."),
            AIMessage(content="No eval."),
        ]
    )
    await _invoke(agent, invoke_mode, config)
    persisted = checkpoint(agent)
    assert all(persisted)
    with monkeypatch.context() as forbidden:
        forbidden.setattr(_repl, "Runtime", _forbid_allocation)
        forbidden.setattr(_repl, "ThreadWorker", _forbid_allocation)
        await _invoke(agent, invoke_mode, config)
        assert checkpoint(agent) == persisted
        rebuilt = build(
            [
                AIMessage(content="Still no eval."),
                _call("counter += 1; counter", "resume"),
                _call("counter += 1; counter", "again"),
                AIMessage(content="Resumed."),
            ]
        )
        await _invoke(rebuilt, invoke_mode, config)
        assert checkpoint(rebuilt) == persisted
    result = await _invoke(rebuilt, invoke_mode, config)
    assert _results(result)[-2:] == ["<result>42</result>", "<result>43</result>"]


@pytest.mark.parametrize("invoke_mode", ["invoke", "ainvoke"])
@pytest.mark.parametrize("mode", ["thread", "turn", "call"])
async def test_live_bindings_change_before_first_and_subsequent_eval(
    invoke_mode, mode
) -> None:
    @tool("lookup")
    def replacement() -> str:
        """Return a replacement result."""
        return "replacement"

    middleware = CodeInterpreterMiddleware(mode=mode, ptc=["lookup"])
    state = middleware.before_agent({}, None)
    runtime = ToolRuntime(
        state=state,
        context={},
        config={},
        stream_writer=lambda _: None,
        tools=middleware.tools,
        tool_call_id="live-bindings",
        store=None,
    )

    def prepare(tools):
        return middleware._prepare_for_call(SimpleNamespace(state=state, tools=tools))

    async def evaluate(code):
        if invoke_mode == "ainvoke":
            return await middleware.tools[0].ainvoke({"code": code, "runtime": runtime})
        return middleware.tools[0].invoke({"code": code, "runtime": runtime})

    try:
        original = prepare([lookup])
        assert original == prepare([lookup])
        prepare([replacement])
        assert middleware._registry.get_if_exists(state["_quickjs_slot_id"]) is None
        result = await evaluate("await tools.lookup({})")
        assert result.content == "<result>replacement</result>"
        prepare([lookup])
        result = await evaluate("await tools.lookup({})")
        assert result.content == "<result>available</result>"
        prepare([])
        result = await evaluate("typeof tools.lookup")
        assert result.content == "<result>undefined</result>"
    finally:
        middleware.after_agent(state, None)
    assert not middleware._registry._slots

"""Checkpointed JavaScript fan-out resumes logical subagents without restarting work."""

from __future__ import annotations

import asyncio
from collections import Counter
from typing import Any

from deepagents import create_deep_agent
from deepagents.middleware.subagents import CompiledSubAgent
from langchain_core.messages import AIMessage, HumanMessage, ToolMessage
from langgraph.checkpoint.memory import InMemorySaver
from langgraph.graph import END, START, MessagesState, StateGraph
from langgraph.types import Command, interrupt

from langchain_quickjs import CodeInterpreterMiddleware
from tests._common import FakeChatModel


def _child(
    name: str,
    pauses: int,
    work: Counter[str],
    approved: dict[str, list[str]],
    predecessor: asyncio.Event | None,
) -> CompiledSubAgent:
    async def perform_work(state: MessagesState) -> dict[str, Any]:
        work[name] += 1
        return {"messages": [AIMessage(content=f"{name} result")]}

    async def post_work_hook(state: MessagesState) -> dict[str, Any]:
        if predecessor is not None:
            await predecessor.wait()
        decisions = [interrupt({"child": name, "hook": i}) for i in range(pauses)]
        approved[name] = decisions
        return {}

    graph = StateGraph(MessagesState)
    graph.add_node("work", perform_work)
    graph.add_node("post_work_hook", post_work_hook)
    graph.add_edge(START, "work")
    graph.add_edge("work", "post_work_hook")
    graph.add_edge("post_work_hook", END)
    return CompiledSubAgent(
        name=name,
        description=f"Run {name} work and its completion hooks.",
        runnable=graph.compile(),
    )


async def test_fanout_keeps_three_ids_across_checkpoint_resumes() -> None:
    """Completed work survives sibling hooks and repeated parent-node reexecution."""
    work: Counter[str] = Counter()
    approved: dict[str, list[str]] = {}
    finished = {name: asyncio.Event() for name in ("fast", "review", "cost")}
    children = [
        _child("fast", 0, work, approved, None),
        _child("review", 1, work, approved, finished["fast"]),
        _child("cost", 3, work, approved, finished["review"]),
    ]
    middleware = CodeInterpreterMiddleware(tool_name="js_eval")
    code = (
        "await Promise.all(['fast', 'review', 'cost'].map(subagentType => "
        "task({description: 'Do the assigned work', label: 'Worker', "
        "subagentType})))"
    )
    model = FakeChatModel(
        messages=iter(
            [
                AIMessage(
                    content="",
                    tool_calls=[
                        {
                            "name": "js_eval",
                            "args": {"code": code},
                            "id": "fanout_eval",
                            "type": "tool_call",
                        }
                    ],
                ),
                AIMessage(content="All work returned."),
            ]
        )
    )
    agent = create_deep_agent(
        model=model,
        middleware=[middleware],
        subagents=children,
        checkpointer=InMemorySaver(),
    )
    config = {"configurable": {"thread_id": "subagent-replay"}}
    events: list[dict[str, Any]] = []
    names: dict[str, str] = {}
    rounds: list[list[dict[str, Any]]] = []
    payload: dict[str, Any] | Command = {
        "messages": [HumanMessage(content="Run the three workers.")]
    }
    try:
        for _ in range(6):
            attempt: list[dict[str, Any]] = []
            async for mode, chunk in agent.astream(
                payload, config, stream_mode=["custom", "updates"]
            ):
                if mode != "custom" or chunk.get("type") != "subagent":
                    continue
                events.append(chunk)
                attempt.append(chunk)
                if chunk["phase"] == "start":
                    names[chunk["id"]] = chunk["subagent_type"]
                elif chunk["phase"] == "complete":
                    finished[names[chunk["id"]]].set()
            rounds.append(attempt)
            snapshot = await agent.aget_state(config)
            if not snapshot.interrupts:
                break
            payload = Command(
                resume={item.id: "approved" for item in snapshot.interrupts}
            )
        else:
            msg = "Subagent hooks did not finish after five resumes"
            raise AssertionError(msg)
    finally:
        middleware._registry.close()

    assert len(rounds) == 5
    assert work == {"fast": 1, "review": 1, "cost": 1}
    assert approved == {"fast": [], "review": ["approved"], "cost": ["approved"] * 3}
    assert len(names) == 3
    assert {event["eval_id"] for event in events} == {"fanout_eval"}
    assert {
        names[event["id"]] for event in rounds[0] if event["phase"] == "complete"
    } == {"fast"}
    for attempt in rounds:
        assert {
            (event["id"], event["subagent_type"])
            for event in attempt
            if event["phase"] == "start"
        } == set(names.items())
    assert {event["id"] for event in rounds[-1] if event["phase"] == "complete"} == set(
        names
    )
    assert not snapshot.next
    assert snapshot.values["messages"][-1].content == "All work returned."
    results = [
        message
        for message in snapshot.values["messages"]
        if isinstance(message, ToolMessage) and message.tool_call_id == "fanout_eval"
    ]
    assert len(results) == 1
    assert "<error" not in results[0].content
    for name in finished:
        assert f"{name} result" in results[0].content

"""Thread/loop-affinity regression tests for QuickJS PTC async dispatch."""

from __future__ import annotations

import asyncio
from collections.abc import (
    Iterator,  # noqa: TC003 — pydantic resolves annotations at runtime
)
from typing import TYPE_CHECKING, Any

from deepagents import create_deep_agent
from langchain_core.language_models.fake_chat_models import GenericFakeChatModel
from langchain_core.messages import AIMessage, HumanMessage, ToolMessage
from langchain_core.runnables import RunnableLambda
from langchain_core.tools import tool
from pydantic import Field

from langchain_quickjs import CodeInterpreterMiddleware

if TYPE_CHECKING:
    from collections.abc import Sequence


class _FakeChatModel(GenericFakeChatModel):
    """GenericFakeChatModel whose bind_tools returns self."""

    messages: Iterator[AIMessage | str] = Field(exclude=True)

    def bind_tools(self, tools: Sequence[Any], **_: Any) -> _FakeChatModel:
        del tools
        return self


def _script(code: str, *, final_message: str = "done") -> Iterator[AIMessage]:
    return iter(
        [
            AIMessage(
                content="",
                tool_calls=[
                    {
                        "name": "eval",
                        "args": {"code": code},
                        "id": "call_1",
                        "type": "tool_call",
                    },
                ],
            ),
            AIMessage(content=final_message),
        ]
    )


def _eval_tool_message(result: dict[str, Any]) -> ToolMessage:
    messages = [
        m for m in result["messages"] if isinstance(m, ToolMessage) and m.name == "eval"
    ]
    assert messages, "expected at least one eval ToolMessage"
    return messages[-1]


def _assert_result_contains(content: str, expected: str) -> None:
    assert "<error" not in content, content
    assert "<result" in content, content
    assert expected in content, content


def _make_agent(
    code: str,
    middleware: CodeInterpreterMiddleware,
    *,
    final_message: str = "done",
) -> Any:
    return create_deep_agent(
        model=_FakeChatModel(messages=_script(code, final_message=final_message)),
        middleware=[middleware],
    )


@tool("current_loop_id")
async def current_loop_id() -> str:
    """Return the running loop id for loop-affinity assertions."""
    await asyncio.sleep(0)
    return str(id(asyncio.get_running_loop()))


async def test_quickjs_async_ptc_runs_tools_on_outer_loop() -> None:
    """PTC tool coroutines run on the caller loop, not the worker loop."""
    outer_loop_id = str(id(asyncio.get_running_loop()))
    result = await _make_agent(
        "await tools.currentLoopId({})",
        CodeInterpreterMiddleware(ptc=[current_loop_id]),
    ).ainvoke(
        {
            "messages": [
                HumanMessage(
                    content="Use the eval tool and call currentLoopId via PTC."
                )
            ]
        }
    )

    tool_message = _eval_tool_message(result)
    _assert_result_contains(tool_message.content, outer_loop_id)


async def test_quickjs_async_task_global_subagent_loop_affinity_e2e() -> None:
    """E2E: the top-level `task()` global runs compiled subagents on the caller loop.

    `task` is reserved and cannot be exposed via `ptc` (it is always the global),
    so the loop-affinity guarantee is exercised through the global dispatch path.
    """
    outer_loop_id = id(asyncio.get_running_loop())
    owner_loop = asyncio.get_running_loop()
    subagent_loop_ids: list[int] = []

    def _subagent_sync(state: dict[str, Any], config: Any) -> dict[str, Any]:
        del state, config
        return {"messages": [AIMessage(content="subagent-ok")]}

    async def _subagent_async(state: dict[str, Any], config: Any) -> dict[str, Any]:
        del state, config
        subagent_loop_ids.append(id(asyncio.get_running_loop()))
        # Affine guard: awaiting this from a different loop raises the
        # same "Future attached to a different loop" runtime error.
        future = owner_loop.create_future()
        owner_loop.call_soon_threadsafe(future.set_result, None)
        await future
        return {"messages": [AIMessage(content="subagent-ok")]}

    subagent_runnable = RunnableLambda(_subagent_sync, afunc=_subagent_async)
    agent = create_deep_agent(
        model=_FakeChatModel(
            messages=_script(
                "await task({description: 'say hi', "
                "subagentType: 'researcher', label: 'greet'})",
                final_message="done",
            )
        ),
        subagents=[
            {
                "name": "researcher",
                "description": "returns one short answer",
                "runnable": subagent_runnable,
            }
        ],
        middleware=[
            CodeInterpreterMiddleware(),
        ],
    )

    result = await agent.ainvoke(
        {"messages": [HumanMessage(content="Use eval and call task for researcher")]},
        config={"configurable": {"thread_id": "task-global-loop-affinity"}},
    )
    tool_message = _eval_tool_message(result)
    _assert_result_contains(tool_message.content, "subagent-ok")
    assert subagent_loop_ids
    assert all(loop_id == outer_loop_id for loop_id in subagent_loop_ids)


async def test_quickjs_task_global_available_without_ptc_e2e() -> None:
    """E2E: top-level `task()` works without exposing PTC tools."""

    def _subagent_sync(state: dict[str, Any], config: Any) -> dict[str, Any]:
        del state, config
        return {"messages": [AIMessage(content="subagent-ok")]}

    async def _subagent_async(state: dict[str, Any], config: Any) -> dict[str, Any]:
        del state, config
        return {"messages": [AIMessage(content="subagent-ok")]}

    subagent_runnable = RunnableLambda(_subagent_sync, afunc=_subagent_async)
    agent = create_deep_agent(
        model=_FakeChatModel(
            messages=_script(
                "await task({description: 'say hi', "
                "subagentType: 'researcher', label: 'greet'})",
                final_message="done",
            )
        ),
        subagents=[
            {
                "name": "researcher",
                "description": "returns one short answer",
                "runnable": subagent_runnable,
            }
        ],
        middleware=[
            CodeInterpreterMiddleware(),
        ],
    )

    result = await agent.ainvoke(
        {
            "messages": [
                HumanMessage(content="Use eval and call the researcher through task.")
            ]
        },
        config={"configurable": {"thread_id": "task-global-no-ptc"}},
    )
    tool_message = _eval_tool_message(result)
    _assert_result_contains(tool_message.content, "subagent-ok")

